// Parse Faceted Search Parameters
// Extracts query and facet fields from input

const inputData = $input.all();
const outputs = [];

for (const item of inputData) {
  const input = item.json;

  // Build facet fields array (what to group by)
  const facetFields = [];

  if (input.facet_by_department !== false) {
    facetFields.push("department");
  }

  if (input.facet_by_type !== false) {
    facetFields.push("document_type_category");
  }

  if (input.facet_by_standard) {
    facetFields.push("standard_compliance");
  }

  // If no facets specified, default to department and type
  if (facetFields.length === 0) {
    facetFields.push("department", "document_type_category");
  }

  // Build search payload
  const searchPayload = {
    query: input.query || "",
    facet_fields: facetFields,
    limit: input.limit !== undefined ? parseInt(input.limit) : 50,
    min_score: input.min_score !== undefined ? parseFloat(input.min_score) : 0.6,
    min_quality: input.min_quality !== undefined ? parseFloat(input.min_quality) : 0.65
  };

  // Validate limit
  if (searchPayload.limit < 1 || searchPayload.limit > 100) {
    throw new Error("Limit must be between 1 and 100");
  }

  outputs.push({ json: searchPayload });
}

return outputs;

// Format Faceted Search Results
// Formats API response with facet counts and sample documents

const inputData = $input.all();
const outputs = [];

for (const item of inputData) {
  const response = item.json;

  // Check if we have results
  if (!response.results || response.results.length === 0) {
    outputs.push({
      json: {
        success: true,
        message: "No results found. Try: (1) broader search terms, (2) lower min_score threshold, or (3) different facet fields.",
        query: response.query || "",
        facets: {},
        results_count: 0,
        results: []
      }
    });
    continue;
  }

  // Format facet counts
  const formattedFacets = {};

  if (response.facets) {
    for (const [field, counts] of Object.entries(response.facets)) {
      formattedFacets[field] = Object.entries(counts)
        .map(([value, count]) => ({
          value: value,
          count: count,
          percentage: ((count / response.results.length) * 100).toFixed(1) + "%"
        }))
        .sort((a, b) => b.count - a.count);
    }
  }

  // Format document results - FIXED: Access metadata properly
  const formattedResults = response.results.map((result, index) => {
    const meta = result.metadata || {};
    return {
      rank: index + 1,
      document_code: result.document_id || "Unknown",
      title: result.document_name || "Untitled Document",
      department: meta.department || "Unknown",
      document_type: meta.document_type || "Unknown",
      version: meta.document_version || "N/A",
      standard_compliance: meta.standard_compliance || "",
      content_snippet: result.content ? result.content.substring(0, 200) + "..." : "",
      relevance_score: result.score ? result.score.toFixed(3) : "N/A",
      quality_score: meta.quality_score ? meta.quality_score.toFixed(3) : "N/A",
      sharepoint_url: meta.document_url || null,
      citation: `**${result.document_id || "Unknown"}** (${result.document_name || "Untitled"}${meta.document_version ? ", v" + meta.document_version : ""})`
    };
  });

  // Create formatted response
  const formattedResponse = {
    success: true,
    search_type: "faceted",
    query: response.query || "(exploration mode)",
    results_count: formattedResults.length,

    // Facet breakdown
    facets: formattedFacets,

    // Top 10 results as examples
    sample_results: formattedResults.slice(0, 10),

    // All results for further processing
    all_results: formattedResults,

    // Generate summary
    summary: generateFacetSummary(formattedFacets, formattedResults, response.query),

    // Metadata
    metadata: {
      facet_fields: response.facet_fields || [],
      search_time_ms: response.search_time_ms || null,
      total_documents_searched: response.total_points || null,
      min_score_threshold: response.min_score || 0.6,
      min_quality_threshold: response.min_quality || 0.95
    }
  };

  outputs.push({ json: formattedResponse });
}

// Helper function to generate summary
function generateFacetSummary(facets, results, query) {
  if (results.length === 0) {
    return `No results found${query ? ` for "${query}"` : ""}.`;
  }

  let summary = `Found ${results.length} documents${query ? ` for "${query}"` : ""}\n\n`;

  // Add facet breakdown
  for (const [field, counts] of Object.entries(facets)) {
    const fieldName = field === "department" ? "Departments" : 
                      field === "document_type_category" ? "Document Types" :
                      field === "standard_compliance" ? "Standards" : field;

    summary += `${fieldName}:\n`;
    const top5 = counts.slice(0, 5);
    top5.forEach(item => {
      summary += `  - ${item.value}: ${item.count} docs (${item.percentage})\n`;
    });

    if (counts.length > 5) {
      summary += `  - ... and ${counts.length - 5} more\n`;
    }
    summary += "\n";
  }

  // Add sample documents
  summary += "Sample documents:\n";
  const samples = results.slice(0, 3);
  samples.forEach((r, i) => {
    summary += `${i + 1}. ${r.citation}\n`;
  });

  return summary;
}

return outputs;
